import sys, json

def solve(req):
    initial = req['initial']
    final = req['final']
    txs = req['transactions']
    n = len(txs)

    # Precedence: A.end <= B.start  =>  A must occur before B.
    preds = [0] * n
    for i in range(n):
        ei = txs[i]['end']
        for j in range(n):
            if i != j and ei <= txs[j]['start']:
                preds[j] |= 1 << i

    # Per-transaction write summaries for cheap necessary-condition pruning.
    # fmaps[i][k]: over-approx of the set of values tx i can leave on key k
    #   (None marks absence). For a key k with write-effects e1..em in order:
    #     f(prefix + [put v])      = {v}
    #     f(prefix + [del])        = {None}
    #     f(prefix + [cas _ new])  = {new (or None if new is null)} | f(prefix)
    #   (a failed CAS exposes the value produced by the prefix; the entry value
    #   is covered separately by the current value of k).
    # wput[i]: keys with an unconditional put somewhere in tx i.
    # wdel[i]: keys tx i may make absent (del or cas with new=None).
    fmaps = []; wput = []; wdel = []
    for t in txs:
        per = {}
        pu = set(); dl = set()
        for op in t['ops']:
            c = op[0]
            if c == 'put':
                per.setdefault(op[1], []).append(op[2]); pu.add(op[1])
            elif c == 'del':
                per.setdefault(op[1], []).append(None); dl.add(op[1])
            elif c == 'cas':
                per.setdefault(op[1], []).append(('cas', op[3]))
                if op[3] is None:
                    dl.add(op[1])
        fm = {}
        for k, effs in per.items():
            s = set()
            for e in effs:
                if isinstance(e, tuple):      # cas
                    s = ({e[1]} if e[1] is not None else {None}) | s
                elif e is None:               # del
                    s = {None}
                else:                         # put
                    s = {e}
            fm[k] = frozenset(s)
        fmaps.append(fm); wput.append(pu); wdel.append(dl)

    final_t = tuple(sorted(final.items()))
    simcache = {}
    dead = set()

    def simulate(i, mtup):
        # Run transaction i on map mtup; return resulting map tuple or None.
        m = dict(mtup)
        for op in txs[i]['ops']:
            c = op[0]
            if c == 'get':
                if m.get(op[1]) != op[2]:
                    return None
            elif c == 'put':
                m[op[1]] = op[2]
            elif c == 'del':
                m.pop(op[1], None)
            elif c == 'cas':
                ok = m.get(op[1]) == op[2]
                if ok != op[4]:
                    return None
                if ok:
                    if op[3] is None:
                        m.pop(op[1], None)
                    else:
                        m[op[1]] = op[3]
            else:  # scan
                low, high = op[1], op[2]
                if [[k, m[k]] for k in sorted(m) if low <= k < high] != op[3]:
                    return None
        return tuple(sorted(m.items()))

    def feasible(remaining, mtup):
        # Sound (no false negative) necessary conditions on the final map.
        cur = dict(mtup)
        # Rule 1: every key present in final or in the current map must have
        # its required end value (None = absent) in the reachable-value set.
        for k in set(final) | set(cur):
            allowed = {cur.get(k)}
            r = remaining
            while r:
                b = r & -r; i = b.bit_length() - 1; r ^= b
                fm = fmaps[i].get(k)
                if fm:
                    allowed |= fm
            if final.get(k) not in allowed:
                return False
        # Rule 2: a key not in final that some remaining tx writes with an
        # unconditional put stays present unless some remaining tx can delete it.
        r = remaining
        while r:
            b = r & -r; i = b.bit_length() - 1; r ^= b
            for k in wput[i]:
                if k not in final:
                    rr = remaining
                    found = False
                    while rr:
                        bb = rr & -rr; j = bb.bit_length() - 1; rr ^= bb
                        if k in wdel[j]:
                            found = True
                            break
                    if not found:
                        return False
        return True

    sys.setrecursionlimit(10000)

    def dfs(remaining, mtup):
        if remaining == 0:
            return () if mtup == final_t else None
        key = (remaining, mtup)
        if key in dead:
            return None
        if not feasible(remaining, mtup):
            dead.add(key)
            return None
        r = remaining
        while r:
            b = r & -r; i = b.bit_length() - 1; r ^= b
            if preds[i] & remaining:
                continue  # a predecessor of i is still unplaced
            ck = (i, mtup)
            if ck in simcache:
                nxt = simcache[ck]
            else:
                nxt = simulate(i, mtup)
                simcache[ck] = nxt
            if nxt is None:
                continue
            out = dfs(remaining ^ (1 << i), nxt)
            if out is not None:
                return (i,) + out
        dead.add(key)
        return None

    res = dfs((1 << n) - 1, tuple(sorted(initial.items())))
    if res is None:
        return {"order": None}
    return {"order": [txs[i]['id'] for i in res]}

if __name__ == '__main__':
    out = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        out.append(json.dumps(solve(json.loads(line))))
    if out:
        sys.stdout.write('\n'.join(out) + '\n')
